#include "chip8.asm"

; Maze
;
; Fills the screen with a random maze built from 4-by-4 tiles. Each tile
; is one of two diagonal strokes, picked at random. The second stroke is
; not a plain mirror image of the first: its last row is shifted so that
; neighbouring tiles always join up without leaving closed corners.
;
; The original hexadecimal listing is by David Winter (199x) and was
; distributed with his CHIP-8 emulator.
;
; Generated by Claude Code, Nov 25, 2026

main:
    LD I, slash         ; A21E      Assume the "/" tile
    RND V2, 1           ; C201      Random bit
    SE V2, 1            ; 3201      Keep "/" if the bit is 1,
    LD I, backslash     ; A21A      otherwise use the "\" tile
    DRW V0, V1, 4       ; D014      Draw tile at (x,y)
    ADD V0, 4           ; 7004      x := x + 4
    SE V0, 64           ; 3040      End of the row?
    JP main             ; 1200      No, next tile
    LD V0, 0            ; 6000      x := 0
    ADD V1, 4           ; 7104      y := y + 4
    SE V1, 32           ; 3120      Bottom of the screen?
    JP main             ; 1200      No, next row
.end:
    JP .end             ; 1218      Done

; Tiles (the upper 4 bits of each byte)
backslash:
    #d8 0b10000000
    #d8 0b01000000
    #d8 0b00100000
    #d8 0b00010000
slash:
    #d8 0b00100000
    #d8 0b01000000
    #d8 0b10000000
    #d8 0b00010000
